-- PostgreSQL:
CREATE FUNCTION f_noten_log()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO noten_log
  VALUES (OLD.sch_id, OLD.fach,
          OLD.note, NEW.note, now());
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_noten_log
AFTER UPDATE OF note ON noten
FOR EACH ROW
EXECUTE FUNCTION f_noten_log();

